/// `Hack.Parameter`.
pub mod parameter {
    #![allow(unused_imports, clippy::all)]
    use crate::yojson::safe::T as Json;

    /// `Hack.Parameter.t`.
    #[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
    pub struct T {
        pub name: super::name::T,
        pub type_: Option<super::type_::T>,
        pub is_inout: bool,
        pub is_variadic: bool,
        pub default_value: Option<String>,
        pub attributes: Vec<super::user_attribute::T>,
        pub type_info: Option<super::type_info::T>,
        pub readonly: Option<super::readonly_kind::T>,
        pub named: Option<super::named_kind::T>,
    }

    /// `Hack.Parameter.to_json`.
    pub fn to_json(x: &T) -> Json {
        let T { name, type_, is_inout, is_variadic, default_value, attributes, type_info, readonly, named } = x;
        let mut fields: Vec<(String, Json)> = vec![
            ("name".to_string(), super::name::to_json(name)),
            ("isInout".to_string(), Json::Bool(*is_inout)),
            ("isVariadic".to_string(), Json::Bool(*is_variadic)),
            ("attributes".to_string(), Json::List(attributes.iter().map(|x| super::user_attribute::to_json(x)).collect())),
        ];
        if let Some(type_) = type_ {
            fields.insert(0, ("type".to_string(), super::type_::to_json(type_)));
        }
        if let Some(default_value) = default_value {
            fields.insert(0, ("defaultValue".to_string(), Json::String(default_value.clone())));
        }
        if let Some(type_info) = type_info {
            fields.insert(0, ("typeInfo".to_string(), super::type_info::to_json(type_info)));
        }
        if let Some(readonly) = readonly {
            fields.insert(0, ("readonly".to_string(), super::readonly_kind::to_json(readonly)));
        }
        if let Some(named) = named {
            fields.insert(0, ("named".to_string(), super::named_kind::to_json(named)));
        }
        Json::Assoc(fields)
    }

    #[cfg(test)]
    pub fn of_json(j: &Json) -> T {
        T {
            name: { let y = crate::write_symbol_info::glean::util::test_json::field(j, "name"); super::name::of_json(y) },
            type_: crate::write_symbol_info::glean::util::test_json::field_opt(j, "type").map(|y| super::type_::of_json(y)),
            is_inout: { let y = crate::write_symbol_info::glean::util::test_json::field(j, "isInout"); crate::write_symbol_info::glean::util::test_json::bool(y) },
            is_variadic: { let y = crate::write_symbol_info::glean::util::test_json::field(j, "isVariadic"); crate::write_symbol_info::glean::util::test_json::bool(y) },
            default_value: crate::write_symbol_info::glean::util::test_json::field_opt(j, "defaultValue").map(|y| crate::write_symbol_info::glean::util::test_json::string(y)),
            attributes: { let y = crate::write_symbol_info::glean::util::test_json::field(j, "attributes"); crate::write_symbol_info::glean::util::test_json::list(y).iter().map(|y| super::user_attribute::of_json(y)).collect() },
            type_info: crate::write_symbol_info::glean::util::test_json::field_opt(j, "typeInfo").map(|y| super::type_info::of_json(y)),
            readonly: crate::write_symbol_info::glean::util::test_json::field_opt(j, "readonly").map(|y| super::readonly_kind::of_json(y)),
            named: crate::write_symbol_info::glean::util::test_json::field_opt(j, "named").map(|y| super::named_kind::of_json(y)),
        }
    }
}

